# rapids-g (rapids TASK-036): top/rapids_top_base_16ch.f on the -g base.
# Filelist for rapids_g_top_base with the 16-channel register map
# Location: projects/components/dma-ip/rapids/rtl/filelists/top_g/rapids_g_top_base_16ch.f
#
# The base is one module for both register-map sizes. This file picks the
# map: its regblock (rapids_regs_16ch, generated by bin/peakrdl_generate.py from the RDL that bin/gen_rapids_regs_16ch.py derives)
# and the regsel include dir that tells the base which regblock and glue to use.
# The regblock comes first: the base uses its package.

+incdir+$REPO_ROOT/projects/components/dma-ip/rapids/rtl/top/generated/regsel_16ch

# ---- PeakRDL register file (split SRC/SNK), 16 channels ----
$REPO_ROOT/projects/components/dma-ip/rapids/regs/generated_16ch/rtl/rapids_regs_16ch_pkg.sv
$REPO_ROOT/projects/components/dma-ip/rapids/regs/generated_16ch/rtl/rapids_regs_16ch.sv

-f $REPO_ROOT/projects/components/dma-ip/rapids/rtl/filelists/top_g/rapids_g_top_base_common.f

# ---- The base itself, last: it uses the regblock package and the regsel
#      include dir above ----
$REPO_ROOT/projects/components/dma-ip/rapids/rtl/top_g/generated/rapids_g_top_base.sv
